namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        var validationFailure = GetValidationFailure(principal, resource, request);
        if (validationFailure is not null)
            return new AccessDecision(false, validationFailure, true);

        return DecideWithValidContext(principal!, resource!, request!, delegations);
    }

    private static string? GetValidationFailure(Principal? principal, Resource? resource, AccessRequest? request)
    {
        if (principal is null || resource is null || request is null)
            return "missing-context";
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return "invalid-identity";
        if (principal.Suspended)
            return "principal-suspended";
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return "tenant-mismatch";
        if (resource.Locked && request.Action != "read")
            return "resource-locked";
        if (request.MinuteOfDay is < 0 or > 1439)
            return "invalid-time";
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return "challenge-required";

        return null;
    }

    private static AccessDecision DecideWithValidContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var authorization = GetAuthorizationFacts(principal, resource, request, delegations);

        if (request.BreakGlass)
            return DecideBreakGlass(request, authorization.Administrator);

        var denial = GetPolicyDenial(resource, request, authorization);
        if (denial is { } denied)
            return new AccessDecision(false, denied.Reason, denied.RequiresAudit);

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            authorization.Delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private static AuthorizationFacts GetAuthorizationFacts(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        return new AuthorizationFacts(administrator, operatorRole, auditor, owner, delegated);
    }

    private static AccessDecision DecideBreakGlass(AccessRequest request, bool administrator)
    {
        if (!administrator || !request.StrongAuthentication)
            return new AccessDecision(false, "invalid-break-glass", true);

        return new AccessDecision(true, "break-glass", true);
    }

    private static PolicyDenial? GetPolicyDenial(
        Resource resource,
        AccessRequest request,
        AuthorizationFacts authorization)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return new PolicyDenial("strong-authentication-required", true);
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return new PolicyDenial("trusted-network-required", true);
        if (request.Action == "delete" && !authorization.Administrator)
            return new PolicyDenial("administrator-required", true);
        if (request.Action == "write" && !authorization.CanWrite)
            return new PolicyDenial("write-not-authorised", true);
        if (request.Action == "read" && !authorization.CanRead)
            return new PolicyDenial("read-not-authorised", false);
        if (request.Action is not ("read" or "write" or "delete"))
            return new PolicyDenial("unknown-action", true);

        return null;
    }

    private readonly record struct AuthorizationFacts(
        bool Administrator,
        bool Operator,
        bool Auditor,
        bool Owner,
        bool Delegated)
    {
        public bool CanWrite => Administrator || Operator || Owner || Delegated;
        public bool CanRead => Administrator || Operator || Auditor || Owner || Delegated;
    }

    private readonly record struct PolicyDenial(string Reason, bool RequiresAudit);
}
